<template><view class="page-shell"><view class="page-hero"><view class="ink-nav"><text class="nav-back" @click="goBack">‹</text>提交报销</view></view><view class="content-layer form-body safe-bottom"><view class="form-card"><text class="field-label">报销事项</text><input v-model="form.title" class="field-input" placeholder="例如：课堂材料采购" /><text class="field-label">报销金额（元）</text><input v-model="form.amount" class="field-input" type="digit" placeholder="例如：86.50" /><text class="field-label">关联项目</text><input v-model="form.project_name" class="field-input" placeholder="选填" /><text class="field-label">说明</text><textarea v-model="form.note" class="field-textarea" maxlength="300" placeholder="选填，填写采购说明或凭证备注" /></view><button class="submit-button" :loading="submitting" :disabled="submitting" @click="submit">提交报销申请</button></view></view></template>
<script setup lang="ts">import { reactive,ref } from 'vue';import { submitReimbursement } from '@/api/user';import { getErrorMessage } from '@/constants/errors';const form=reactive({title:'',amount:'',project_name:'',note:''});const submitting=ref(false);const goBack=()=>uni.navigateBack();const submit=async()=>{if(!form.title.trim()||Number(form.amount)<=0){uni.showToast({title:'请填写报销事项和有效金额',icon:'none'});return}submitting.value=true;try{await submitReimbursement({...form,amount:Number(form.amount)});uni.showToast({title:'报销已提交',icon:'success'});setTimeout(goBack,700)}catch(error:any){uni.showToast({title:getErrorMessage(error?.code,error?.message||'提交失败'),icon:'none'})}finally{submitting.value=false}};</script>
<style lang="scss" scoped>@import '@/styles/variables.scss';@import '@/styles/mixins.scss';.page-hero{@include ink-header(184rpx);padding:64rpx 34rpx 38rpx;box-sizing:border-box}.nav-back{position:absolute;left:0;font-size:48rpx;line-height:1}.form-body{padding-bottom:148rpx}.form-card{@include soft-card;padding:28rpx}.field-label{display:block;margin:22rpx 0 12rpx;color:$text-secondary;font-size:26rpx}.field-label:first-child{margin-top:0}.field-input,.field-textarea{width:100%;box-sizing:border-box;padding:20rpx;border-radius:14rpx;background:rgba(31,78,95,.06);color:$text-primary;font-size:27rpx}.field-input{height:82rpx}.field-textarea{min-height:150rpx;line-height:1.55}.submit-button{position:fixed;left:28rpx;right:28rpx;bottom:calc(24rpx + env(safe-area-inset-bottom));height:88rpx;border-radius:22rpx;background:$ink-blue;color:#fff;font-size:30rpx;font-weight:700}</style>
